"use client";

import { motion, useReducedMotion, useScroll, useTransform } from "motion/react";
import { useRef } from "react";
import type { ComponentProps, ReactNode } from "react";

export type ScrollDrivenAnimationPrimitiveProps = Omit<ComponentProps<typeof motion.div>, "children" | "ref"> & {
  children: ReactNode;
};

export function ScrollDrivenAnimationPrimitive({ children, ...props }: ScrollDrivenAnimationPrimitiveProps) {
  const target = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const { scrollYProgress } = useScroll({ target, offset: ["start end", "end start"] });
  const progress = useTransform(scrollYProgress, [0.1, 0.8], [80, -80]);

  return (
    <motion.div
      {...props}
      ref={target}
      style={{ ...props.style, y: reduceMotion ? 0 : progress }}
    >
      {children}
    </motion.div>
  );
}
